// Turns each uploaded file into a Gemini generateContent request body.
const PROMPT = "You are an accounts-payable assistant. Extract the data printed on this invoice.\n\nRules:\n- Copy values exactly as printed. Do NOT correct arithmetic, even if the numbers look wrong.\n- Dates as YYYY-MM-DD. If a field is not printed (e.g. no due date), return null.\n- currency: 3-letter ISO code (USD, EUR, GBP, CAD, ...), inferred from symbols if needed.\n- Numbers as plain numbers without currency symbols or thousands separators.\n- tax_rate as a decimal (8% -> 0.08). If only a tax amount is printed, return null for tax_rate.\n- For each line item, choose the best category from: Software & Subscriptions, Office Supplies, Equipment, Travel, Meals & Entertainment, Advertising & Marketing, Professional Services, Shipping & Logistics, Rent & Utilities, Other.\n";
const SCHEMA = {"type": "OBJECT", "properties": {"vendor": {"type": "STRING", "nullable": true}, "vendor_address": {"type": "STRING", "nullable": true}, "bill_to": {"type": "STRING", "nullable": true}, "invoice_number": {"type": "STRING", "nullable": true}, "invoice_date": {"type": "STRING", "nullable": true}, "due_date": {"type": "STRING", "nullable": true}, "currency": {"type": "STRING", "nullable": true}, "line_items": {"type": "ARRAY", "items": {"type": "OBJECT", "properties": {"description": {"type": "STRING"}, "quantity": {"type": "NUMBER", "nullable": true}, "unit_price": {"type": "NUMBER", "nullable": true}, "amount": {"type": "NUMBER", "nullable": true}, "category": {"type": "STRING", "enum": ["Software & Subscriptions", "Office Supplies", "Equipment", "Travel", "Meals & Entertainment", "Advertising & Marketing", "Professional Services", "Shipping & Logistics", "Rent & Utilities", "Other"]}}, "required": ["description", "amount", "category"]}}, "subtotal": {"type": "NUMBER", "nullable": true}, "tax_rate": {"type": "NUMBER", "nullable": true}, "tax": {"type": "NUMBER", "nullable": true}, "total": {"type": "NUMBER", "nullable": true}}, "required": ["vendor", "invoice_number", "invoice_date", "currency", "line_items", "total"]};
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const keys = Object.keys(item.binary || {});
  if (!keys.length) throw new Error('No file found on item ' + i);
  for (const key of keys) {   // the upload form allows several files at once
    const bin = item.binary[key];
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    const mime = bin.mimeType && bin.mimeType !== 'application/octet-stream'
      ? bin.mimeType
      : (/\.pdf$/i.test(bin.fileName || '') ? 'application/pdf' : 'image/jpeg');
    out.push({ json: {
      file_name: bin.fileName || key,
      body: {
        contents: [{ parts: [
          { inline_data: { mime_type: mime, data: buf.toString('base64') } },
          { text: PROMPT },
        ] }],
        generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: SCHEMA },
      },
    } });
  }
}
return out;

function validate(inv) {
  const TOL = 0.02;
  const flags = [];
  const items = inv.line_items || [];
  const itemsSum = Math.round(items.reduce((s, it) => s + (it.amount || 0), 0) * 100) / 100;
  const subtotal = inv.subtotal, tax = inv.tax || 0, total = inv.total;
  if (!inv.vendor || !inv.invoice_number || total == null) flags.push('missing_required_fields');
  if (!inv.due_date) flags.push('missing_due_date');
  if (subtotal != null && Math.abs(itemsSum - subtotal) > TOL) flags.push('items_sum_mismatch');
  if (total != null && items.length && Math.abs(itemsSum + tax - total) > TOL) flags.push('total_mismatch');
  for (const it of items) {
    if (it.quantity != null && it.unit_price != null && it.amount != null &&
        Math.abs(it.quantity * it.unit_price - it.amount) > TOL) { flags.push('line_amount_mismatch'); break; }
  }
  return flags;
}

// Parses Gemini's JSON, runs deterministic checks, and shapes rows for Google Sheets.
const requests = $('Build Gemini request').all();
return $input.all().map((item, i) => {
  const fileName = (requests[i] && requests[i].json.file_name) || 'unknown';
  const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
  let inv = null, error = '';
  try {
    const text = item.json.candidates[0].content.parts[0].text;
    inv = JSON.parse(text);
  } catch (e) {
    error = item.json.error ? JSON.stringify(item.json.error).slice(0, 200) : 'Could not read model output';
  }
  if (!inv) {
    return { json: { invoice: { processed_at_utc: now, file: fileName, status: 'Extraction failed', issues: error }, lines: [] } };
  }
  const items = inv.line_items || [];
  const itemsSum = Math.round(items.reduce((s, it) => s + (it.amount || 0), 0) * 100) / 100;
  const flags = validate(inv);
  const invoice = {
    processed_at_utc: now,
    file: fileName,
    status: flags.length ? 'Needs review' : 'OK',
    issues: flags.join(', '),
    vendor: inv.vendor,
    invoice_number: inv.invoice_number,
    invoice_date: inv.invoice_date,
    due_date: inv.due_date || '',
    currency: inv.currency,
    subtotal: inv.subtotal,
    tax_rate: inv.tax_rate,
    tax: inv.tax,
    total: inv.total,
    line_items_sum: itemsSum,
    line_item_count: items.length,
    bill_to: inv.bill_to,
    vendor_address: inv.vendor_address,
  };
  const lines = items.map((it, n) => ({
    invoice_number: inv.invoice_number,
    vendor: inv.vendor,
    invoice_date: inv.invoice_date,
    line: n + 1,
    description: it.description,
    category: it.category,
    quantity: it.quantity,
    unit_price: it.unit_price,
    amount: it.amount,
    currency: inv.currency,
  }));
  return { json: { invoice, lines } };
});
